CREATE TABLE IF NOT EXISTS events (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, capacity INT NOT NULL, day5Capacity INT NULL, day6Capacity INT NULL, maxGroup INT NOT NULL DEFAULT 20, holdMinutes INT NOT NULL DEFAULT 20, cashHoldMinutes INT NOT NULL DEFAULT 1440, allowKidsOnly INT NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS users (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, passwordHash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, active INT NOT NULL DEFAULT 1, createdAt VARCHAR(30) NOT NULL);

CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(36) PRIMARY KEY, reference VARCHAR(40) NOT NULL UNIQUE, eventId VARCHAR(36) NOT NULL, eventDate VARCHAR(10) NOT NULL, name VARCHAR(120) NOT NULL, mobile VARCHAR(10) NOT NULL, email VARCHAR(190) NOT NULL, adults INT NOT NULL, kids INT NOT NULL, people INT NOT NULL, amount INT NOT NULL, method VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, holdUntil VARCHAR(30) NOT NULL, ticketNonce VARCHAR(64) NOT NULL, qrHash VARCHAR(64) NULL UNIQUE, checkedInAt VARCHAR(30) NULL, createdAt VARCHAR(30) NOT NULL, updatedAt VARCHAR(30) NOT NULL, FOREIGN KEY(eventId) REFERENCES events(id), CHECK(adults >= 0 AND kids >= 0 AND people > 0 AND amount >= 0));

CREATE TABLE IF NOT EXISTS payments (id VARCHAR(36) PRIMARY KEY, bookingId VARCHAR(36) NOT NULL UNIQUE, orderId VARCHAR(100) NULL UNIQUE, paymentId VARCHAR(100) NULL UNIQUE, amount INT NOT NULL, status VARCHAR(30) NOT NULL, receipt VARCHAR(100) NULL, approvedBy VARCHAR(36) NULL, approvedAt VARCHAR(30) NULL, FOREIGN KEY(bookingId) REFERENCES bookings(id), FOREIGN KEY(approvedBy) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS otp_verifications (id VARCHAR(36) PRIMARY KEY, mobile VARCHAR(10) NOT NULL, otpHash VARCHAR(64) NOT NULL, expiresAt VARCHAR(30) NOT NULL, attempts INT NOT NULL DEFAULT 0, verifiedAt VARCHAR(30) NULL, createdAt VARCHAR(30) NOT NULL);

CREATE TABLE IF NOT EXISTS checkins (id VARCHAR(36) PRIMARY KEY, bookingId VARCHAR(36) NOT NULL UNIQUE, staffId VARCHAR(36) NOT NULL, eventDate VARCHAR(10) NOT NULL, adults INT NOT NULL, kids INT NOT NULL, people INT NOT NULL, idempotencyKey VARCHAR(100) NOT NULL UNIQUE, createdAt VARCHAR(30) NOT NULL, FOREIGN KEY(bookingId) REFERENCES bookings(id), FOREIGN KEY(staffId) REFERENCES users(id));

CREATE TABLE IF NOT EXISTS webhook_events (id VARCHAR(100) PRIMARY KEY, eventType VARCHAR(80) NOT NULL, createdAt VARCHAR(30) NOT NULL);

CREATE TABLE IF NOT EXISTS notification_logs (id VARCHAR(36) PRIMARY KEY, bookingId VARCHAR(36) NOT NULL, type VARCHAR(50) NOT NULL, status VARCHAR(30) NOT NULL, attempts INT NOT NULL DEFAULT 0, nextAttemptAt VARCHAR(30) NOT NULL, lastError VARCHAR(200) NULL, sentAt VARCHAR(30) NULL, UNIQUE(bookingId,type), FOREIGN KEY(bookingId) REFERENCES bookings(id));

CREATE TABLE IF NOT EXISTS audit_logs (id VARCHAR(36) PRIMARY KEY, userId VARCHAR(36) NULL, action VARCHAR(80) NOT NULL, entityId VARCHAR(100) NOT NULL, createdAt VARCHAR(30) NOT NULL);

CREATE TABLE IF NOT EXISTS booking_requests (id VARCHAR(100) PRIMARY KEY, mobile VARCHAR(10) NOT NULL, bookingId VARCHAR(36) NOT NULL UNIQUE, fingerprint VARCHAR(64) NOT NULL, FOREIGN KEY(bookingId) REFERENCES bookings(id));

CREATE TABLE IF NOT EXISTS ticket_batches (bookingId VARCHAR(36) PRIMARY KEY, createdAt VARCHAR(30) NOT NULL, FOREIGN KEY(bookingId) REFERENCES bookings(id));

CREATE TABLE IF NOT EXISTS individual_tickets (id VARCHAR(36) PRIMARY KEY, bookingId VARCHAR(36) NOT NULL, ordinal INT NOT NULL, category VARCHAR(10) NOT NULL, eventDate VARCHAR(10) NOT NULL, nonce VARCHAR(64) NOT NULL, qrHash VARCHAR(64) NOT NULL UNIQUE, approvedAt VARCHAR(30) NULL, approvedBy VARCHAR(36) NULL, approvalKey VARCHAR(100) NULL UNIQUE, createdAt VARCHAR(30) NOT NULL, UNIQUE(bookingId,ordinal), FOREIGN KEY(bookingId) REFERENCES bookings(id), FOREIGN KEY(approvedBy) REFERENCES users(id));
